function SaveButton() {
  const { toast } = useToast();
  return (
    <button type="button" onClick={() => toast({ title: "Changes saved", description: "Your profile is up to date.", intent: "success" })}>
      Save
    </button>
  );
}

<ToastProvider>
  <SaveButton />
</ToastProvider>

